require "set"

module App
  class OrderFilter
    def initialize(blocked)
      @blocked = blocked.to_set
    end

    # Wrong: returns the blocked ones instead of the allowed ones.
    def allowed(orders)
      orders.select { |o| @blocked.include?(o) }
    end
  end
end

module App
  class OrderFilter
    def initialize(blocked)
      @blocked = blocked
    end

    # Correct output but still O(n*m): @blocked stays an Array, so include?
    # is a linear scan. Busts the time budget on the large input.
    def allowed(orders)
      orders.reject { |o| @blocked.include?(o) }
    end
  end
end
